/**
 * Test-only stub for Next.js's `server-only` guard package.
 *
 * The real package exports a module that throws when it is pulled into a client
 * bundle. That check is a build-time concern; under the test runner there is no
 * bundler, so importing it fails outright and any module that guards itself with
 * `import "server-only"` becomes untestable. Resolving it here (via NODE_PATH in
 * the `test` script) lets those modules be unit-tested without weakening the
 * guard in the real build, where the genuine package is still what resolves.
 */
module.exports = {};
